<?php $uf = strtoupper(fort_input('uf')); ?>
<div class="representatives-layout"><div><span class="eyebrow">ATENDIMENTO COMERCIAL</span><h2>Mais perto do seu projeto.</h2><p>Selecione seu estado para consultar os representantes cadastrados. Nossa equipe também pode orientar você pelo atendimento direto.</p><form method="get" class="representative-filter"><label for="uf">Seu estado</label><div class="button-row"><select name="uf" id="uf"><option value="">Selecione uma UF</option><?php foreach (array('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') as $state): ?><option <?php selected($uf, $state); ?>><?php echo esc_html($state); ?></option><?php endforeach; ?></select><button class="button button-small">Consultar <?php echo fort_icon('search'); ?></button></div></form></div><div class="representative-results" aria-live="polite"><?php $reps = $uf ? get_posts(array('post_type' => 'fort_representante', 'post_status' => 'publish', 'posts_per_page' => 50, 'meta_key' => '_fort_uf', 'meta_value' => $uf)) : array(); if ($reps): foreach ($reps as $rep): ?><article class="representative-card"><?php echo fort_icon('pin'); ?><h3><?php echo esc_html($rep->post_title); ?></h3><p><?php echo esc_html(get_post_meta($rep->ID, '_fort_regiao', true)); ?></p><?php if ($phone = get_post_meta($rep->ID, '_fort_telefone', true)): ?><a href="tel:<?php echo esc_attr(preg_replace('/\D/', '', $phone)); ?>"><?php echo esc_html($phone); ?></a><?php endif; ?><?php if ($email = get_post_meta($rep->ID, '_fort_email', true)): ?><a href="mailto:<?php echo esc_attr($email); ?>"><?php echo esc_html($email); ?></a><?php endif; ?></article><?php endforeach; else: ?><div class="regional-contact"><?php echo fort_icon('chat'); ?><h3><?php echo $uf ? 'Vamos encontrar o melhor atendimento para você.' : 'Conte com a equipe Fort.'; ?></h3><p><?php echo $uf ? 'Fale com a central comercial para consultar o atendimento da sua região.' : 'Ajudamos você a encontrar o contato ideal para o seu projeto.'; ?></p><a class="button" href="<?php echo esc_url(fort_whatsapp($uf ? 'Olá! Preciso de atendimento comercial para o estado ' . $uf . '.' : 'Olá! Gostaria de falar com um representante.')); ?>" target="_blank" rel="noopener noreferrer">Falar com o comercial <?php echo fort_icon('arrow'); ?></a></div><?php endif; ?></div></div>
